/**
 * EngageIntent - Combat engagement behavior
 *
 * Attacks visible targets with shooting and optional movement.
 * High priority intent that activates when targets are detected.
 *
 * **Usage**
 *
 * ```js
 * body.ai.addIntent(new EngageIntent({
 *   fireRate: 2.0,       // Shots per second
 *   engageRange: 25,     // Max engagement distance
 *   optimalRange: 15,    // Preferred combat distance
 *   strafeEnabled: true, // Strafe during combat
 *   priority: 80         // High priority
 * }));
 * ```
 *
 * **Events Emitted**
 *
 * | Event | When | Payload |
 * |-------|------|---------|
 * | `engage` | Combat starts (intent activates) | `{ targetPosition, targetDistance }` |
 * | `fire` | Weapon fires | `{ origin, direction, target }` |
 *
 * ```js
 * body.ai.addEventListener('engage', (event) => {
 *   console.log('Engaging at distance:', event.targetDistance);
 * });
 *
 * body.ai.addEventListener('fire', (event) => {
 *   createMuzzleFlash(event.origin);
 *   playSound('gunshot');
 * });
 * ```
 *
 * @module @three-blocks/pro/ai/EngageIntent
 * @class EngageIntent
 * @extends Intent
 * @short Combat engagement behavior
 * @category AI
 * @tags AI, Intent, Combat, Shooting, Events
 */
export class EngageIntent extends Intent {
    /**
     * Events this intent can emit.
     * @type {string[]}
     * @static
     */
    static events: string[];
    /**
     * Create a new EngageIntent.
     *
     * @param {Object} [config] - Configuration options.
     * @param {number} [config.fireRate=2.0] - Shots per second.
     * @param {number} [config.engageRange=25] - Maximum engagement distance.
     * @param {number} [config.optimalRange=15] - Preferred combat distance.
     * @param {number} [config.minRange=5] - Minimum distance before backing up.
     * @param {boolean} [config.strafeEnabled=true] - Enable strafing.
     * @param {number} [config.strafeInterval=2.0] - Time between strafe direction changes.
     * @param {number} [config.priority=80] - Selection priority.
     * @param {string} [config.weaponType='hitscan'] - Weapon type (hitscan, projectile, hybrid).
     * @param {number} [config.projectileSpeed=40] - Projectile speed for lead calculation.
     * @param {number} [config.damage=10] - Damage per hit.
     */
    constructor(config?: {
        fireRate?: number;
        engageRange?: number;
        optimalRange?: number;
        minRange?: number;
        strafeEnabled?: boolean;
        strafeInterval?: number;
        priority?: number;
        weaponType?: string;
        projectileSpeed?: number;
        damage?: number;
    });
    /**
     * Shots per second.
     * @type {number}
     * @private
     */
    private _fireRate;
    /**
     * Maximum engagement distance.
     * @type {number}
     * @private
     */
    private _engageRange;
    /**
     * Preferred combat distance.
     * @type {number}
     * @private
     */
    private _optimalRange;
    /**
     * Minimum distance before backing up.
     * @type {number}
     * @private
     */
    private _minRange;
    /**
     * Enable strafing.
     * @type {boolean}
     * @private
     */
    private _strafeEnabled;
    /**
     * Time between strafe direction changes.
     * @type {number}
     * @private
     */
    private _strafeInterval;
    /**
     * Weapon type for this engagement.
     * @type {string}
     * @private
     */
    private _weaponType;
    /**
     * Projectile speed for lead calculation.
     * @type {number}
     * @private
     */
    private _projectileSpeed;
    /**
     * Damage per hit.
     * @type {number}
     * @private
     */
    private _damage;
    /**
     * Time since last shot.
     * @type {number}
     * @private
     */
    private _lastFireTime;
    /**
     * Current strafe direction (1 = right, -1 = left).
     * @type {number}
     * @private
     */
    private _strafeDirection;
    /**
     * Time since last strafe direction change.
     * @type {number}
     * @private
     */
    private _strafeSwitchTimer;
    /**
     * Time in this engagement.
     * @type {number}
     * @private
     */
    private _engageTime;
    /**
     * Set fire rate.
     *
     * @param {number} value - Shots per second.
     */
    set fireRate(value: number);
    /**
     * Get fire rate.
     *
     * @returns {number} Shots per second.
     */
    get fireRate(): number;
    /**
     * Configure engagement parameters.
     *
     * @param {Object} config - Configuration object.
     * @returns {EngageIntent} This instance for chaining.
     */
    set(config: any): EngageIntent;
}
import { Intent } from './Intent.js';
